import{_ as r,o as s,c as a,ah as t}from"./chunks/framework.ChH6X6u6.js";const c=JSON.parse('{"title":"Paie","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/paie.md","filePath":"src/guide/admin/paie.md"}'),l={name:"guide/admin/paie.md"};function i(n,e,o,u,p,d){return s(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="paie" tabindex="-1">Paie <a class="header-anchor" href="#paie" aria-label="Permalink to &quot;Paie&quot;">​</a></h1><p>La page <strong>Personnel → Paie</strong> prépare les bulletins de paie du mois. Seuls les administrateurs la voient, et seulement si votre licence comprend le module <strong>Ressources humaines</strong>.</p><p>Le bulletin reste simple : un salaire de base, plus des primes, moins des retenues, toutes saisies à la main. ERA ne calcule <strong>pas</strong> les cotisations sociales ni l&#39;impôt sur le salaire : si vous les retenez, ajoutez-les comme retenues, avec le montant calculé par votre comptable.</p><h2 id="avant-la-premiere-paie-le-salaire-de-base" tabindex="-1">Avant la première paie : le salaire de base <a class="header-anchor" href="#avant-la-premiere-paie-le-salaire-de-base" aria-label="Permalink to &quot;Avant la première paie : le salaire de base&quot;">​</a></h2><p>Chaque employé payé doit avoir un <strong>Salaire de base mensuel</strong> sur sa fiche (voir <a href="/era-guide/guide/admin/personnel-utilisateurs.html#gerer-les-fiches-et-contrats-du-personnel">Personnel et comptes utilisateurs</a>). Le champ est facultatif : un employé sans salaire de base n&#39;a pas de bulletin.</p><p>La page Paie liste, sous <strong>Employés sans salaire de base</strong>, les employés actifs à qui il manque ce montant. <strong>Ouvrir les fiches employé</strong> mène à la liste pour le compléter.</p><h2 id="preparer-la-paie-du-mois" tabindex="-1">Préparer la paie du mois <a class="header-anchor" href="#preparer-la-paie-du-mois" aria-label="Permalink to &quot;Préparer la paie du mois&quot;">​</a></h2><ol><li>Sous <strong>Préparer une paie</strong>, choisissez le <strong>Mois</strong> (le mois suivant la dernière paie est proposé).</li><li>Cliquez sur <strong>Préparer la paie</strong>.</li></ol><p>ERA crée un bulletin pour chaque employé <strong>actif</strong> qui a un salaire de base. Le bulletin reprend le nom, le poste et le site de l&#39;employé à ce moment-là, et son salaire de base actuel.</p><p>Les primes et retenues du dernier bulletin de chaque employé sont <strong>reprises</strong> : une prime de transport mensuelle ou une avance remboursée en plusieurs fois n&#39;est pas à ressaisir. Retirez celles qui ne valent plus pour ce mois.</p><p>Un mois ne se prépare qu&#39;une fois. Pour recommencer, supprimez le brouillon (voir plus bas).</p><h2 id="ajuster-les-bulletins" tabindex="-1">Ajuster les bulletins <a class="header-anchor" href="#ajuster-les-bulletins" aria-label="Permalink to &quot;Ajuster les bulletins&quot;">​</a></h2><p>Tant que la paie est en <strong>Brouillon</strong>, chaque ligne du tableau a un bouton <strong>Modifier</strong> :</p><ol><li>Corrigez au besoin le <strong>Salaire de base</strong> de ce mois.</li><li>Cliquez sur <strong>Ajouter une prime</strong> ou <strong>Ajouter une retenue</strong>, puis saisissez le <strong>Libellé</strong> (par exemple « Prime de logement », « Avance sur salaire ») et le <strong>Montant</strong>, en FCFA.</li><li>Retirez une ligne avec l&#39;icône de corbeille.</li><li>Vérifiez le <strong>Net à payer</strong> affiché en bas, puis cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Le net à payer est le salaire de base, plus les primes, moins les retenues. Le tableau affiche, pour chaque employé, le salaire de base, les primes, les retenues et le net, avec le total du mois.</p><p>Modifier le salaire de base d&#39;un bulletin ne change pas la fiche de l&#39;employé : pour une augmentation durable, mettez aussi la fiche à jour.</p><h2 id="cloturer-la-paie" tabindex="-1">Clôturer la paie <a class="header-anchor" href="#cloturer-la-paie" aria-label="Permalink to &quot;Clôturer la paie&quot;">​</a></h2><p>Une fois les salaires versés, cliquez sur <strong>Clôturer la paie</strong> et confirmez. La paie passe à <strong>Clôturée</strong> :</p><ul><li>les bulletins ne peuvent plus être modifiés ;</li><li>chaque employé peut télécharger le sien dans <strong>Mes bulletins de paie</strong> (voir plus bas).</li></ul><p>Pour corriger une erreur après la clôture, cliquez sur <strong>Rouvrir</strong> : les bulletins redeviennent modifiables et disparaissent de l&#39;espace des employés jusqu&#39;à la prochaine clôture.</p><p>Une paie en brouillon peut aussi être <strong>supprimée</strong>, avec tous ses bulletins. Une paie clôturée doit d&#39;abord être rouverte.</p><h2 id="imprimer-et-exporter" tabindex="-1">Imprimer et exporter <a class="header-anchor" href="#imprimer-et-exporter" aria-label="Permalink to &quot;Imprimer et exporter&quot;">​</a></h2><p>Depuis la paie du mois :</p><table tabindex="0"><thead><tr><th>Bouton</th><th>Contenu</th></tr></thead><tbody><tr><td>Tous les bulletins (PDF)</td><td>un bulletin par page, à imprimer et faire signer</td></tr><tr><td>PDF (sur une ligne)</td><td>le bulletin d&#39;un seul employé</td></tr><tr><td>État de paie (CSV)</td><td>une ligne par employé : poste, site, salaire de base, primes, brut, retenues, net, et total</td></tr><tr><td>Écritures comptables (CSV)</td><td>les écritures de paie du mois, à reprendre dans votre logiciel comptable</td></tr></tbody></table><p>Tant que la paie est en brouillon, les bulletins PDF portent la mention « Brouillon ».</p><h3 id="ecritures-comptables" tabindex="-1">Écritures comptables <a class="header-anchor" href="#ecritures-comptables" aria-label="Permalink to &quot;Écritures comptables&quot;">​</a></h3><p>Les écritures sont datées du dernier jour du mois, dans le journal <strong>PA</strong>. Pour chaque employé :</p><ul><li>le net à payer : débit <strong>661100</strong> (rémunérations du personnel), crédit <strong>422000</strong> (personnel, rémunérations dues) ;</li><li>les retenues, s&#39;il y en a : débit <strong>661100</strong>, crédit <strong>428000</strong> (personnel, charges à payer).</li></ul><p>Ces comptes suivent le plan SYSCOHADA. Faites-les valider par votre comptable : pour en changer, contactez edPage.</p><h2 id="mes-bulletins-de-paie-employes" tabindex="-1">Mes bulletins de paie (employés) <a class="header-anchor" href="#mes-bulletins-de-paie-employes" aria-label="Permalink to &quot;Mes bulletins de paie (employés)&quot;">​</a></h2><p>Tout membre du personnel qui a une fiche employé trouve ses bulletins dans <strong>Personnel → Mes bulletins de paie</strong> : le mois, le brut, les retenues et le net, avec <strong>Télécharger</strong> pour le PDF.</p><p>Seuls les mois <strong>clôturés</strong> y apparaissent. Un employé ne voit que ses propres bulletins.</p><p>Si le compte n&#39;est relié à aucune fiche employé, la page l&#39;indique : l&#39;administration doit créer la fiche.</p>',33)])])}const g=r(l,[["render",i]]);export{c as __pageData,g as default};
